/**
 * The contract `dialog.tsx` and `dialog.web.tsx` both implement. Separate
 * module for the usual reason: Metro resolves `./dialog` to `dialog.web.tsx`
 * on web, so the web file cannot import shared types from `./dialog` without
 * importing itself.
 *
 * This is the surface both platforms honour. The web half widens every part to
 * radix's own props on top of it — `modal`, `forceMount`, `onOpenAutoFocus`, a
 * `div`'s attributes on the sections — so a DOM call site written against
 * shadcn's `dialog` compiles unchanged; those extras are web only and live in
 * `dialog.web.tsx`, not here. A shared contract is also the only thing that
 * makes the platform pair checkable — TypeScript resolves the native file and
 * never compares the two, so `scripts/check-registry-build.mjs` compares the
 * exported names instead.
 */
import type { ReactNode } from "react";

export type DialogProps = {
  /**
   * Controlled when passed. Leave `open` out and the dialog keeps its own state, opened by a
   * `DialogTrigger` and shut by a `DialogClose` — shadcn's uncontrolled form.
   */
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  defaultOpen?: boolean | undefined;
  children?: ReactNode;
};

export type DialogTriggerProps = {
  /**
   * Hand the press handler to the single child rather than wrapping it. Always
   * pass it, for the reason `popover-base.ts` gives: a `Pressable` wrapping a
   * `Button` never fires on native, because the inner pressable claims the touch.
   */
  asChild?: boolean | undefined;
  children: ReactNode;
};

/**
 * `DialogContent` takes three things the section slots do not.
 *
 * `onEscapeKeyDown` and `onInteractOutside` are the two ways a dialog closes without
 * the caller asking, and a form dialog with unsaved edits needs to intercept both.
 * Native has one of each — the hardware back button and the backdrop press — so they
 * are honoured there too rather than being web-only.
 */
export type DialogContentProps = DialogSectionProps & {
  /** Draw the corner close button. Default `true`. */
  showCloseButton?: boolean | undefined;
  onEscapeKeyDown?: ((event: Event) => void) | undefined;
  onInteractOutside?: ((event: Event) => void) | undefined;
  /** `undefined` passed explicitly is how "nothing describes this" is said to radix. */
  "aria-describedby"?: string | undefined;
  /**
   * `alertdialog` for a question that interrupts — "Discard your changes?" — which assistive
   * technology announces as urgent rather than as a place to work. Default `dialog`.
   */
  role?: "dialog" | "alertdialog" | undefined;
};

/** Closes the dialog it is inside. `asChild` hands the press to a `Button` rather than wrapping it. */
export type DialogCloseProps = {
  asChild?: boolean | undefined;
  className?: string | undefined;
  children?: ReactNode;
};

/**
 * `DialogPortal` and `DialogOverlay` are shadcn's parts for assembling a custom content pane.
 * On native the `Modal` is already the portal, so the portal is a pass-through and the overlay is
 * the same dimmed layer `DialogContent` draws.
 */
export type DialogPortalProps = { children?: ReactNode };
export type DialogOverlayProps = { className?: string | undefined };

export type DialogFooterProps = DialogSectionProps & {
  /** Append an outline "Close" button that shuts the dialog. Default `false`. */
  showCloseButton?: boolean | undefined;
};

/** Every part inside a `Dialog` — content, header, footer, title, description. */
export type DialogSectionProps = {
  className?: string | undefined;
  children?: ReactNode;
};

/**
 * The native dialog: a transparent `Modal` with a dimmed backdrop and a centred
 * card, matching what radix renders on web closely enough that no call site
 * needs to branch.
 *
 * What does not carry over from radix, and is not faked here: the focus trap
 * and the scroll lock (a `Modal` already owns the screen) and the enter/exit
 * animations beyond the `fade` the `Modal` does itself. `Escape` becomes
 * `onRequestClose`, which is the Android back button.
 *
 * `open === false` renders nothing at all, so a dialog's body unmounts between
 * openings exactly as it does on web.
 */

import {
  Children,
  cloneElement,
  createContext,
  isValidElement,
  type ReactElement,
  useContext,
  useRef,
  useState,
} from "react";
import { Modal, Pressable, Text, View } from "react-native";
import { Button } from "@/components/ui/button";
import type {
  DialogCloseProps,
  DialogContentProps,
  DialogFooterProps,
  DialogOverlayProps,
  DialogPortalProps,
  DialogProps,
  DialogSectionProps,
  DialogTriggerProps,
} from "@/components/ui/dialog-base";
import { X } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

/** The open side of the same problem, read by `DialogTrigger`. */
const DialogOpenContext = createContext<(open: boolean) => void>(() => {});

/**
 * `onEscapeKeyDown` belongs to `DialogContent` — that is where radix puts it — but the
 * thing that fires it here is the hardware back button, which `Modal` reports to
 * `Dialog`. The handler is published upward through a ref rather than downward, because
 * the component that has it is below the component that hears the event.
 */
const DialogEscapeContext = createContext<{ current: ((event: Event) => void) | undefined }>({
  current: undefined,
});

/**
 * Radix wires its `Close` up through the `Root` it is nested in. There is no
 * equivalent on native, so `Dialog` publishes the closer and `DialogContent`
 * — which owns both the backdrop and the X — reads it.
 */
const DialogCloseContext = createContext<() => void>(() => {});

function Dialog({ open, onOpenChange, defaultOpen = false, children }: DialogProps) {
  // Uncontrolled state kept unconditionally — hooks cannot be conditional — and read only when
  // the caller passed no `open`, the same arrangement as `popover.tsx`.
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const isOpen = open ?? uncontrolled;
  const setOpen = (next: boolean) => {
    if (open === undefined) setUncontrolled(next);
    onOpenChange?.(next);
  };
  const escapeRef = useRef<((event: Event) => void) | undefined>(undefined);

  // The trigger has to render while the dialog is shut, and everything else must not.
  // On web that falls out of radix's portal; here the children are split by type, because
  // `Modal` renders nothing at all until `visible` and a trigger inside it would never
  // appear. This is why `DialogTrigger` must be a direct child of `Dialog`.
  const parts = Children.toArray(children);
  const triggers = parts.filter((c) => isValidElement(c) && c.type === DialogTrigger);
  const rest = parts.filter((c) => !(isValidElement(c) && c.type === DialogTrigger));

  // Android's back button is native's Escape: the one way the dialog closes that the
  // caller did not ask for. `preventDefault` keeps it open, exactly as it does on web.
  const requestClose = () => {
    const handler = escapeRef.current;
    if (!handler) return setOpen(false);
    const event = new Event("keydown", { cancelable: true });
    handler(event);
    if (!event.defaultPrevented) setOpen(false);
  };

  return (
    <DialogOpenContext.Provider value={setOpen}>
      {triggers}
      <DialogEscapeContext.Provider value={escapeRef}>
        <Modal visible={isOpen} transparent animationType="fade" onRequestClose={requestClose}>
          <DialogCloseContext.Provider value={() => setOpen(false)}>
            {rest}
          </DialogCloseContext.Provider>
        </Modal>
      </DialogEscapeContext.Provider>
    </DialogOpenContext.Provider>
  );
}

/**
 * A trigger, so a dialog can own its own open state at the call site.
 *
 * On web this is radix's, which also wires `aria-haspopup` and returns focus. Here
 * it is the press that flips `Dialog`'s open flag — its own state, or the caller's
 * through `onOpenChange` — so the native trigger is the child's `onPress`, cloned.
 */
function DialogTrigger({ asChild, children }: DialogTriggerProps) {
  const open = useContext(DialogOpenContext);
  const show = () => open(true);
  if (asChild && isValidElement(children)) {
    return cloneElement(children as ReactElement<{ onPress?: () => void }>, { onPress: show });
  }
  return (
    <Pressable onPress={show} role="button">
      {children}
    </Pressable>
  );
}

/**
 * Shuts the dialog it is inside — radix's `Close`, for a Cancel button of the caller's own.
 * `asChild` hands the press to the child, for the reason `DialogTrigger` gives.
 */
function DialogClose({ asChild, className, children }: DialogCloseProps) {
  const close = useContext(DialogCloseContext);
  if (asChild && isValidElement(children)) {
    return cloneElement(children as ReactElement<{ onPress?: () => void }>, { onPress: close });
  }
  return (
    // The `role` is hand-written because a `<button>` has no native counterpart.
    <Pressable onPress={close} role="button" className={cn(className)}>
      {children}
    </Pressable>
  );
}

/** The `Modal` is already the portal on native; this is here so a shadcn composition renders. */
function DialogPortal({ children }: DialogPortalProps) {
  return <>{children}</>;
}

/**
 * The dimmed layer, for a caller assembling its own pane. `DialogContent` draws its own, so this
 * is only for content that is not one; it does not close on press — the backdrop `DialogContent`
 * draws is the one that does.
 */
function DialogOverlay({ className }: DialogOverlayProps) {
  return <View pointerEvents="none" className={cn("absolute inset-0 bg-black/80", className)} />;
}

function DialogContent({
  className,
  showCloseButton = true,
  onEscapeKeyDown,
  onInteractOutside,
  role,
  children,
}: DialogContentProps) {
  const close = useContext(DialogCloseContext);
  const escapeRef = useContext(DialogEscapeContext);
  escapeRef.current = onEscapeKeyDown;

  // The backdrop press is native's "interact outside". `preventDefault` on the
  // synthetic event is what a caller uses to keep the dialog open, matching radix.
  const interactOutside = () => {
    if (!onInteractOutside) return close();
    const event = new Event("pointerdown", { cancelable: true });
    onInteractOutside(event);
    if (!event.defaultPrevented) close();
  };
  return (
    <View className="flex-1 items-center justify-center bg-black/80 p-6">
      {/* The backdrop is a sibling laid out underneath rather than a parent of
          the card, because `Pressable` has no `stopPropagation` — nesting the
          card inside it would make every press on the card close the dialog. */}
      <Pressable
        className="absolute inset-0"
        onPress={interactOutside}
        role="button"
        aria-label="Close"
      />
      <View
        {...(role === undefined ? {} : { role })}
        className={cn(
          "w-full max-w-lg gap-4 rounded-lg border border-border bg-background p-6",
          className,
        )}
      >
        {children}
        {showCloseButton ? (
          <Pressable
            className="absolute right-4 top-4 opacity-70"
            onPress={close}
            // The `role` is hand-written because a `<button>` has no native counterpart.
            role="button"
            aria-label="Close"
          >
            <X className="h-4 w-4" />
          </Pressable>
        ) : null}
      </View>
    </View>
  );
}

// `space-y-*` and `space-x-*` are child-combinator utilities nativewind does
// not implement; `gap` is the cross-platform equivalent and behaves the same
// for these two rows.
function DialogHeader({ className, children }: DialogSectionProps) {
  return <View className={cn("gap-1.5", className)}>{children}</View>;
}

function DialogFooter({ className, showCloseButton = false, children }: DialogFooterProps) {
  return (
    <View className={cn("flex-row justify-end gap-2", className)}>
      {children}
      {showCloseButton ? (
        <DialogClose asChild>
          <Button variant="outline">Close</Button>
        </DialogClose>
      ) : null}
    </View>
  );
}

function DialogTitle({ className, children }: DialogSectionProps) {
  return (
    <Text
      // The `role` is hand-written because an `<h2>` has no native counterpart.
      role="heading"
      aria-level={2}
      className={cn("text-lg font-semibold leading-none tracking-tight text-foreground", className)}
    >
      {children}
    </Text>
  );
}

function DialogDescription({ className, children }: DialogSectionProps) {
  return <Text className={cn("text-sm text-muted-foreground", className)}>{children}</Text>;
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};

/**
 * The web dialog: radix, unchanged in behaviour from before the split. It keeps
 * the focus trap, the scroll lock, the `Escape` handler and the enter/exit
 * animations, none of which have a native counterpart worth faking.
 *
 * The exported surface is `dialog-base.ts`'s **plus radix's**: every part also
 * takes the props of the radix part (or the `div`) it renders, exactly as
 * shadcn's `dialog` does, so a DOM call site written against shadcn — `modal`,
 * `onOpenAutoFocus`, `forceMount`, `id`, `data-*`, a `DialogClose asChild` round
 * a Cancel button, a `DialogPortal` + `DialogOverlay` of its own — compiles and
 * behaves unchanged. Those extras are web only; the base is what native honours.
 */

import { Dialog as DialogPrimitive } from "radix-ui";
import type * as React from "react";
import { Button } from "@/components/ui/button";
import type {
  DialogCloseProps,
  DialogContentProps,
  DialogFooterProps,
  DialogOverlayProps,
  DialogPortalProps,
  DialogProps,
  DialogSectionProps,
  DialogTriggerProps,
} from "@/components/ui/dialog-base";
import { X } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

/** The shared contract, widened to what the radix part (or element) underneath accepts. */
type Wide<Base, Radix> = Base & Omit<Radix, keyof Base>;

function Dialog({
  open,
  onOpenChange,
  defaultOpen,
  ...props
}: Wide<DialogProps, React.ComponentProps<typeof DialogPrimitive.Root>>) {
  // Spread only when given: radix goes uncontrolled on `open === undefined` only when the prop is
  // absent, and `exactOptionalPropertyTypes` is what makes the difference expressible.
  return (
    <DialogPrimitive.Root
      data-slot="dialog"
      {...props}
      {...(open === undefined ? {} : { open })}
      {...(onOpenChange === undefined ? {} : { onOpenChange })}
      {...(defaultOpen === undefined ? {} : { defaultOpen })}
    />
  );
}

function DialogTrigger({
  asChild,
  ...props
}: Wide<DialogTriggerProps, React.ComponentProps<typeof DialogPrimitive.Trigger>>) {
  return (
    <DialogPrimitive.Trigger data-slot="dialog-trigger" asChild={asChild ?? false} {...props} />
  );
}

function DialogPortal(
  props: Wide<DialogPortalProps, React.ComponentProps<typeof DialogPrimitive.Portal>>,
) {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />;
}

function DialogClose({
  asChild,
  className,
  ...props
}: Wide<DialogCloseProps, React.ComponentProps<typeof DialogPrimitive.Close>>) {
  return (
    <DialogPrimitive.Close
      data-slot="dialog-close"
      asChild={asChild ?? false}
      {...(className === undefined ? {} : { className })}
      {...props}
    />
  );
}

function DialogOverlay({
  className,
  ...props
}: Wide<DialogOverlayProps, React.ComponentProps<typeof DialogPrimitive.Overlay>>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50 bg-black/80",
        className,
      )}
      {...props}
    />
  );
}

function DialogContent({
  className,
  showCloseButton = true,
  onEscapeKeyDown,
  onInteractOutside,
  "aria-describedby": describedBy,
  role,
  children,
  ...props
}: Wide<DialogContentProps, React.ComponentProps<typeof DialogPrimitive.Content>>) {
  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        {...props}
        {...(onEscapeKeyDown === undefined ? {} : { onEscapeKeyDown })}
        {...(onInteractOutside === undefined ? {} : { onInteractOutside })}
        // Spread only when given: radix sets its own `role="dialog"` and an explicit `undefined`
        // would land after it and take the role away.
        {...(role === undefined ? {} : { role })}
        aria-describedby={describedBy}
        className={cn(
          "bg-background text-foreground data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] fixed left-[50%] top-[50%] z-50 grid w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border p-6 shadow-lg duration-200 sm:rounded-lg",
          className,
        )}
      >
        {children}
        {showCloseButton ? (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className="ring-offset-background focus:ring-ring data-[state=open]:bg-accent data-[state=open]:text-muted-foreground absolute right-4 top-4 rounded-sm opacity-70 transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:pointer-events-none"
          >
            <X className="h-4 w-4" />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>
        ) : null}
      </DialogPrimitive.Content>
    </DialogPortal>
  );
}

function DialogHeader({
  className,
  ...props
}: Wide<DialogSectionProps, React.ComponentProps<"div">>) {
  return (
    <div
      data-slot="dialog-header"
      className={cn("flex flex-col gap-1.5 text-center sm:text-left", className)}
      {...props}
    />
  );
}

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: Wide<DialogFooterProps, React.ComponentProps<"div">>) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn("flex flex-col-reverse gap-2 sm:flex-row sm:justify-end", className)}
      {...props}
    >
      {children}
      {showCloseButton ? (
        <DialogPrimitive.Close asChild>
          <Button variant="outline">Close</Button>
        </DialogPrimitive.Close>
      ) : null}
    </div>
  );
}

function DialogTitle({
  className,
  ...props
}: Wide<DialogSectionProps, React.ComponentProps<typeof DialogPrimitive.Title>>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn("text-lg font-semibold leading-none tracking-tight", className)}
      {...props}
    />
  );
}

function DialogDescription({
  className,
  ...props
}: Wide<DialogSectionProps, React.ComponentProps<typeof DialogPrimitive.Description>>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  );
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};
